end

function UIActivityPromoterNewDialog:Awake()
    self.BossDrawingNodeRectTrans = CfUtils.GetOrAddComponent(self.BossDrawingNode, typeof(RectTransform))
    self.BossDrawingNode2RectTrans = CfUtils.GetOrAddComponent(self.BossDrawingNode2, typeof(RectTransform))
    SetButtonAction(self.InviteFriendsHelpBtn, Bind(self, self._OnClick_InviteFriendsHelpBtn))
    SetButtonAction(self.ReceiveBtn, Bind(self, self._OnClick_ReceiveBtn))
    ---
    self.eventRefresh_ = Events.AddListener(Constants.EventNames.PromoterRefresh, Bind(self, self.DoRefresh))
end

function UIActivityPromoterNewDialog:Start()
    self.co = self.controller:StartCoroutine(util.cs_generator(function()
        while self.isStarting do
            --coroutine.yield(CoYield(3))
            while os.time() - self.startTime <= 3 do
                coroutine.yield()
            end
            self.startTime = os.time()
            while self.isSwitching do
                coroutine.yield()
            end
            if self.maxNo > 1 then
                self.previewIndex = self.previewIndex - 1
                if self.previewIndex < 1 then
                    self.previewIndex = self.maxNo
                end
                ---自动切下一个
                self:UpdateSkinNode(true)
            end
        end
    end))
end

function UIActivityPromoterNewDialog:OnDestroy()
    self.isStarting = false
    if self.eventRefresh_ then
        Events.RemoveListener(Constants.EventNames.PromoterRefresh, self.eventRefresh_)
        self.eventRefresh_ = nil
    end

    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

