-- 刷新入口:
function UIActivityPromoterNewDialog:Refresh(activityDojo, signData)
    self.activityDt   = activityDojo
    self.activityUuid = checkInt(activityDojo.id)
    self.signData = signData
    ---
    self:DoRefresh()
end



function UIActivityPromoterNewDialog:DoRefresh()
    CfUtils.SetActive(self.BossDrawingNode, false)
    CfUtils.SetActive(self.BossDrawingNode2, false)
    self.startTime = os.time()
    self.previewIndex = 1
    GameUtils.Request( "Activity2/spread", {activityUuid = self.activityUuid}, function(request, response)
        if checkNumber(response.errCode) == 0 then

            self.spreadDojoData = response.data
            self.spreadDojoData.shopKeys = table.keys(self.spreadDojoData.shop)
            --self.spreadDojoData.skinSpreadConf.appearanceId = {10202102, 10100501, 10100599}
            self.maxNo = table.count(self.spreadDojoData.skinSpreadConf.appearanceId)
            table.sort(self.spreadDojoData.shopKeys)
            table.sort(self.spreadDojoData.shopKeys, function(a, b)
                local aKey = checkNumber(a)
                local bKey = checkNumber(b)
                local data1 = self.spreadDojoData.shop[tostring(a)]
                local data2 = self.spreadDojoData.shop[tostring(b)]
                if checkNumber(data1.currentStock) == 0 then
                    aKey = 100000
                end
                if checkNumber(data2.currentStock) == 0 then
                    bKey = 100000
                end
                return aKey < bKey
            end)
            ---@type BackpackComponent
            local backpackComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.BackpackComponent)
            backpackComp.backpack[tostring(self.spreadDojoData.skinSpreadConf.costItem)] = checkNumber(self.spreadDojoData.num)
            if isNull(self.spreadDojoData.skinSpreadConf) then 
                printError("后端数据异常 Activity/spread 中没找到 skinSpreadConf ")
                return
            end

            self.promoterSchedulesVO = CfUtils.GetCfVo(AutoIds.IdSetting6172, "ActivityPromoterSchedulesVO", self.spreadDojoData.skinSpreadConf.id)

            SetButtonAction(self.BtnDesc, function()
                CfUtils.ShowModuleToast(self.promoterSchedulesVO.ruleID)
            end)

            local isFreeRewardsActive = self.spreadDojoData.isDrawFreeRewards ~= 1
            if isFreeRewardsActive then 
                SetButtonAction(self.BtnFreeReward, function()
                    self:OnClickBtnFreeReward()
                end)
            end 
            self:RefreshFreeReward( isFreeRewardsActive )

            -- update view
            self:RefreshView()
            self:UpdateRedPoint( isFreeRewardsActive )
        end
    end)
end

function UIActivityPromoterNewDialog:RefreshCurrencyBarInfo()
    if self.spreadDojoData and self.spreadDojoData.skinSpreadConf.costItem then
        ActivityUtils.RefreshNavigatorGoods({self.spreadDojoData.skinSpreadConf.costItem})
    end
end

function UIActivityPromoterNewDialog:GetNextIndex()
    if self.previewIndex + 1 > self.maxNo then
        return 1
    else
        return self.previewIndex + 1
    end
end
function UIActivityPromoterNewDialog:GetPreIndex()
    if self.previewIndex - 1 < 1 then
        return self.maxNo
    else
        return self.previewIndex - 1
    end
end

---UpdateSkinNode
---更新皮肤节点信息
function UIActivityPromoterNewDialog:UpdateSkinNode(isLeft)
    if self.isSwitching then return end
    self.isSwitching = true
    local skinId = checkNumber(self.spreadDojoData.skinSpreadConf.appearanceId[self.previewIndex])-- 10202102
    ----当前显示的节点
    local previewNode = self.previewNode
    local previewNodeTrans = CfUtils.GetOrAddComponent(previewNode, typeof(RectTransform))
    ---@type UnityEngine.RectTransform
    local nextNodeRectTrans = CfUtils.GetOrAddComponent(self.nextNode, typeof(RectTransform))
    local y = nextNodeRectTrans.anchoredPosition3D.y
    nextNodeRectTrans.anchoredPosition3D = Vector3(isLeft and TARGET_RIGHT_X or TARGET_LEFT_X, y, 0)
    self.previewNode = self.nextNode
    self.nextNode = previewNode
    self.previewNode:Execute( skinId )
    local nextSkinId = checkNumber(self.spreadDojoData.skinSpreadConf.appearanceId[self:GetNextIndex()])-- 10202102
    local tween1 = self:DoTween(previewNodeTrans, isLeft and TARGET_LEFT_X or TARGET_RIGHT_X, 0, 0.5)
    local tween2 = self:DoTween(nextNodeRectTrans, TARGET_X, 1, 0.5)
    self:DoTweenGroup(tween1, tween2, function()
        self.isSwitching = false
        self.nextNode:Execute( nextSkinId )
    end)
    -- 左侧 SSR 组件UI内容 + 按钮:
    self:InitCommonBtnRoleNameNode()
end

function UIActivityPromoterNewDialog:StopExpendAnim()
    if isNotNull(self._sequence) then
        self._sequence:Kill(true)
        self._sequence = nil
    end
end

---DoTween
---@param rectTrans UnityEngine.RectTransform
---@param targetX number
---@param duration number
function UIActivityPromoterNewDialog:DoTween(rectTrans, targetX, alpha, duration)
    local tweenSequence = DOTween.Sequence()
    ---@type UnityEngine.CanvasGroup
    local canvasGroup = CfUtils.GetOrAddComponent(rectTrans.gameObject, typeof(CanvasGroup))
    tweenSequence:Insert(0, rectTrans:DOAnchorPos3DX(targetX, duration))
    tweenSequence:Insert(0, canvasGroup:DOFade(alpha, duration))
    tweenSequence:Pause()
    local y = rectTrans.anchoredPosition3D.y
    tweenSequence:OnComplete(function()
        rectTrans.anchoredPosition3D = Vector3.New(targetX, y, 0)
        canvasGroup.alpha = alpha
    end)
    tweenSequence:OnKill(function ()
        rectTrans.anchoredPosition3D = Vector3.New(targetX, y, 0)
        canvasGroup.alpha = alpha
    end)
    return tweenSequence
end

function UIActivityPromoterNewDialog:DoTweenGroup(tween1, tween2, cb)
    self:StopExpendAnim()
    local tweenSequence = DOTween.Sequence()
    tweenSequence:Insert(0, tween1)
    tweenSequence:Insert(0, tween2)
    tweenSequence:OnKill(function()
        self._sequence = nil
        if cb then
            cb()
        end
    end)
    tweenSequence:PlayForward()
end

function UIActivityPromoterNewDialog:RefreshView()
    if not self.activityDt or next(self.activityDt) == nil then
        return
    end
    self:RefreshCurrencyBarInfo()
    -- 右侧 整个 "活动时间" 一块都隐藏;
    --KTool.SetActive( self.TimeGroup, false )
    CfUtils.SetActive(self.BossDrawingNode, true)
    -- 左侧角色皮肤 (大半身像)
    --local skinId = checkNumber(self.spreadDojoData.skinSpreadConf.appearanceId) -- 10202102
    local skinId = checkNumber(self.spreadDojoData.skinSpreadConf.appearanceId[self.previewIndex])-- 10202102
    self.BossDrawingNode:Execute( skinId )
    self.previewNode = self.BossDrawingNode
    local offsetY = self.BossDrawingNodeRectTrans.anchoredPosition3D.y
    self.BossDrawingNodeRectTrans.anchoredPosition3D = Vector3.New(TARGET_X, offsetY, 0)
    CfUtils.GetOrAddComponent(self.BossDrawingNode, typeof(CanvasGroup)).alpha = 1
    self.BossDrawingNode2RectTrans.anchoredPosition3D = Vector3.New(TARGET_X, offsetY, 0)
    CfUtils.GetOrAddComponent(self.BossDrawingNode2, typeof(CanvasGroup)).alpha = 0
    CfUtils.SetActive(self.SwitchArrowNode, self.maxNo > 1)
    if self.maxNo > 1 then
        local nextSkinId = checkNumber(self.spreadDojoData.skinSpreadConf.appearanceId[self:GetNextIndex()])-- 10202102
        self.BossDrawingNode2:Execute( nextSkinId )
        self.nextNode = self.BossDrawingNode2
        self.BossDrawingNode2RectTrans.anchoredPosition3D = Vector3.New(TARGET_RIGHT_X, offsetY, 0)
        CfUtils.GetOrAddComponent(self.BossDrawingNode2, typeof(CanvasGroup)).alpha = 0
        CfUtils.SetActive(self.BossDrawingNode2, true)
        SetButtonAction(self.BtnLeft, function()
            self.previewIndex = self.previewIndex + 1
            if self.previewIndex > self.maxNo then
                self.previewIndex = 1
            end
            self.startTime = os.time()
            self:UpdateSkinNode(false)
        end)
        SetButtonAction(self.BtnRight, function()
            self.previewIndex = self.previewIndex - 1
            if self.previewIndex < 1 then
                self.previewIndex = self.maxNo
            end
            self.startTime = os.time()
            self:UpdateSkinNode(true)
        end)
    end
    -- 左侧 SSR 组件UI内容 + 按钮:
    self:InitCommonBtnRoleNameNode()

    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(self.activityDt.startTime, self.activityDt.endTime))
    ---- 左侧 "收集进度" 节点
    --self:DrawFillNode()


    ---- 左侧, "领取外观按钮":
    --if self.isCanReceive == true then
    --    self.ReceiveBtn:ResetFontStyle("B25", localize("前往兑换"))
    --    CfUtils.SetActive( self.ReceiveBtnFX, true )
    --else
    --    self.ReceiveBtn:ResetFontStyle("B18", localize("前往兑换"))
    --    CfUtils.SetActive( self.ReceiveBtnFX, false )
    --end

    -- 右侧 "邀请好友助力" 按钮上方的 奖励图标
    if self.spreadDojoData.isShare == 0 then 
        CfUtils.SetActive( self.InviteFriendsHelpReward, true )
        self:DrawInviteFriendsHelpReward()
    else 
        CfUtils.SetActive( self.InviteFriendsHelpReward, false )
    end 

    

    self:RefreshReward()
    local detail = string.isEmpty(self.activityDt.detail) and '' or self.activityDt.detail
    -- "活动时间" 下方的一段小字
    CfUtils.FillText(self.Text, detail)
    
end



