    --local skinId = self.spreadDojoData.skinSpreadConf.appearanceId
    local skinId = checkNumber(self.spreadDojoData.skinSpreadConf.appearanceId[self.previewIndex])-- 10202102
    --skinId = 10300602
    ------ 
