            if env then
                env:RefreshSelf(goodsVo.id, goodsVo.quality, function()
                    --CfUtils.CookieSave("UIWelfareMainDialog_Index",self.curIndex)
                end, true)
            end
            --KTool.SetActive(self.BtnRoleGoods.gameObject,true)
