function UIActivityPromoterNewDialog:RefreshReward()
    if not self.LoopListCell.IsListViewInit then
        self.LoopListCell:InitListView(#self.spreadDojoData.shopKeys, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopListCell,#self.spreadDojoData.shopKeys)
    end
end


function UIActivityPromoterNewDialog:GetItemShowNum()
    return checkInt(self.itemShowNum)
end


function UIActivityPromoterNewDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cellNode = listView:NewListViewItem("ActivityPromoterPanel12001401Cell")
    ---@type UIActivityPromoterCellNew
    local nodeEnv  = CfUtils.GetLuaScr(cellNode, "Game.UI.ActivityMainDialog.UIActivityPromoterCellNew")
    local index1Based = index + 1

    local id = self.spreadDojoData.shopKeys[index1Based]

    local data  = self.spreadDojoData.shop[tostring(id)]

    if nodeEnv then

        if self:GetItemShowNum() <= 0 then
            local cellSizeH  = cellNode.CachedRectTransform.rect.height + cellNode.Padding
            self.itemShowNum = math.ceil(listView.ViewPortHeight / cellSizeH)
        end

        if not self.animMapList[index1Based] and (index1Based-1) <= self:GetItemShowNum() then
            self.animMapList[index1Based] = true
            nodeEnv:PlayFadeInAnim(index1Based-1)
        else
            nodeEnv:PlayInitAnim()
        end

        nodeEnv:Refresh(data , index1Based, self.activityUuid)
    end

    return cellNode
end



-- 刷新 活动页面 左侧条目 的红点
function UIActivityPromoterNewDialog:UpdateRedPoint( isFreeRewardsActive_ )
    local isOpenRedPoint   = false
    for _,taskDojo in pairs(self.spreadDojoData.shop) do
        if checkNumber(taskDojo.currentStock) > 0 then
            local consume = table.takeFirst(taskDojo.consume)
            local goodsId = checkNumber(consume.goodsId)
            local num = checkNumber(consume.num)
            local havNo = GoodsUtils.GetThingNo(goodsId)
            if havNo >= num then
                isOpenRedPoint = true
                break
            end
        end 
    end

    isOpenRedPoint = isOpenRedPoint or (isFreeRewardsActive_)
    ActivityUtils.UpdateActivityMainRedPointState(self.activityDt.id, isOpenRedPoint and 0 or -1)
end




return UIActivityPromoterNewDialog
